import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String stringInput = scanner.nextLine();
        StringBuilder modifiedStrBuilder = new StringBuilder();

        // Replace first occurrence of 'at' after the first character
        if (stringInput.length() > 1) {
            modifiedStrBuilder.append(stringInput.charAt(0));
            String remaining = stringInput.substring(1);
            int atIndex = remaining.indexOf("at");
            if (atIndex != -1) {
                // Append part before 'at'
                modifiedStrBuilder.append(remaining.substring(0, atIndex));
                // Append '@'
                modifiedStrBuilder.append("@");
                // Append rest after 'at'
                modifiedStrBuilder.append(remaining.substring(atIndex + 2));
            } else {
                // No 'at' found, append remaining as is
                modifiedStrBuilder.append(remaining);
            }
        } else {
            // String length is 1 or less, just append as is
            modifiedStrBuilder.append(stringInput);
        }

        String modifiedStr = modifiedStrBuilder.toString();

        // Replace 'dot' with '.' in the middle part
        if (modifiedStr.length() > 2) {
            String firstChar = modifiedStr.substring(0, 1);
            String middlePart = modifiedStr.substring(1, modifiedStr.length() - 1).replace("dot", ".");
            String lastChar = modifiedStr.substring(modifiedStr.length() - 1);
            String finalStr = firstChar + middlePart + lastChar;
            System.out.println(finalStr);
        } else {
            // String length is 2 or less, just print as is
            System.out.println(modifiedStr);
        }
        scanner.close();
    }
}
